{
  "verdict": "request_changes",
  "summary": "candidate.py does not correctly round negative amounts with fractional part exactly .5, violating the spec.",
  "findings": [
    {
      "finding_id": "F001",
      "file": "candidate.py",
      "line_start": 2,
      "line_end": 2,
      "severity": "high",
      "description": "The implementation uses `(amount_cents * percent + 50) // 100`, which rounds negative half values toward zero instead of away from zero, breaking the required symmetry `percent_of(-x, p) == -percent_of(x, p)`.",
      "evidence": "For example, percent_of(-1, 50) should return -1 because -0.5 rounds away from zero to -1, but the current code computes (-1 * 50 + 50) // 100 = 0. This violates the contract’s rounding rule for negative amounts."
    }
  ]
}
